#!/usr/bin/env python3
"""Generate protocol/event_codes.h and protocol/event_codes.json from
protocol/event_codes.yaml. See SPEC.md Section 4.7.

Single source of truth for EVENT.event_code, so the firmware enum and the Python-side name
table can never drift apart (unlike record.h's fault_bits / decode_log.py's FAULT_BITS, which
are still hand-synced).
"""
import argparse
import json
from pathlib import Path

import yaml

REPO_ROOT = Path(__file__).resolve().parent.parent


def generate_cpp(events):
    lines = [
        "// GENERATED by tools/gen_protocol.py from protocol/event_codes.yaml. Do not edit by\n"
        "// hand. See SPEC.md Section 4.7.\n"
        "#pragma once\n\n"
        "#include <stdint.h>\n\n"
        "namespace tvc::protocol {\n\n"
        "enum class EventCode : uint8_t {\n"
    ]
    for ev in events:
        lines.append(f"    k{ev['name']} = {ev['code']},\n")
    lines.append("};\n\n")
    lines.append("inline const char* eventCodeName(EventCode c) {\n")
    lines.append("    switch (c) {\n")
    for ev in events:
        lines.append(f'        case EventCode::k{ev["name"]}: return "{ev["name"]}";\n')
    lines.append('        default: return "?";\n')
    lines.append("    }\n")
    lines.append("}\n\n")
    lines.append("}  // namespace tvc::protocol\n")
    return "".join(lines)


def generate_json(events):
    return json.dumps({ev["code"]: ev["name"] for ev in events}, indent=2) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--events", type=Path, default=REPO_ROOT / "protocol" / "event_codes.yaml"
    )
    parser.add_argument(
        "--cpp-out", type=Path, default=REPO_ROOT / "protocol" / "event_codes.h"
    )
    parser.add_argument(
        "--json-out", type=Path, default=REPO_ROOT / "protocol" / "event_codes.json"
    )
    args = parser.parse_args()

    data = yaml.safe_load(args.events.read_bytes())
    if data.get("schema") != 1:
        raise SystemExit(f"{args.events}: unsupported schema {data.get('schema')!r} (expected 1)")
    events = data["events"]

    seen_codes = {}
    for ev in events:
        if ev["code"] in seen_codes:
            raise SystemExit(
                f"{args.events}: code {ev['code']} used by both "
                f"{seen_codes[ev['code']]!r} and {ev['name']!r}"
            )
        seen_codes[ev["code"]] = ev["name"]
        if not (0 <= ev["code"] <= 255):
            raise SystemExit(f"{args.events}: {ev['name']}: code {ev['code']} out of uint8 range")

    args.cpp_out.parent.mkdir(parents=True, exist_ok=True)
    args.cpp_out.write_text(generate_cpp(events))
    args.json_out.write_text(generate_json(events))

    print(
        f"generated {args.cpp_out.relative_to(REPO_ROOT)} and "
        f"{args.json_out.relative_to(REPO_ROOT)} from {args.events.name} "
        f"({len(events)} event codes)"
    )


if __name__ == "__main__":
    main()
